when HTTP_REQUEST {
        #set ident_str "/Services/Identification/Server/";
        #set file_str "/Services/FileService/";   
        #set fulltext_str "/WebService/FulltextService/";
        #set report_str "/gtpReportService/";
        #persist cookie;

   if { [HTTP::cookie exists "ROUTEID"] } {

      # Insert a new cookie with the new name and old cookie's value
      #HTTP::cookie insert name "new-cookie-name" value [HTTP::cookie value "ROUTEID"]
          set cookie_val [HTTP::cookie value "ROUTEID"];  
        log local0.$cookie_val;
   }
    else {
            set cookie_val "";
        }   

        switch -glob [string tolower [HTTP::uri]] {
                "/services/identification/server/*" {
                        pool gtp_identity_pool ;  
                }
                "/services/fileservice/*" {
                        #log local0. "FileService url---[HTTP::uri]";
                        pool gtp_file_pool ; 
                }
                "/gtpreportservice/*" {
                        log local0. "gtpReportService url---[HTTP::uri]";
                        pool gtp_report_pool ;  
                        #node 192.168.133.31:8892;
                }
                "/webservice/fulltextservice/*" {
                        #log local0. "FulltextService url---[HTTP::uri]";
                        pool gtp_fulltext_pool ; 
                }
                "/console*" -
                "/consolecommon/*" -
                "/consoleservices/*" {
                        #log local0. "gtp_console_pool url---[HTTP::uri]";
                        pool gtp_console_pool ; 
                }
                default {
                        #log local0. "default url---[HTTP::uri]";
                        pool gtp_cluster_pool  ;
                }
        }

}

when HTTP_RESPONSE {

        if { $cookie_val!="" } {
                HTTP::cookie value "ROUTEID" $cookie_val;
        }

}
}
